`timescale 1ns / 1ps
// TB for kwt_dot64: reads vectors generated by tools/gen_dot_vectors.py
// vector line format: <act_hex_512b> <wgt_hex_256b> <expected_acc_hex_32b>
module tb_kwt_dot64;

    reg clk = 1'b0;
    reg rst_n = 1'b0;
    reg valid_in = 1'b0;
    reg [64*8-1:0] act_flat = 0;
    reg [64*4-1:0] wgt_flat = 0;
    wire signed [31:0] acc_out;
    wire valid_out;

    always #5 clk = ~clk;

    kwt_dot64 dut (
        .clk      (clk),
        .rst_n    (rst_n),
        .valid_in (valid_in),
        .act_flat (act_flat),
        .wgt_flat (wgt_flat),
        .acc_in   (32'sd0),
        .acc_out  (acc_out),
        .valid_out(valid_out)
    );

    integer fd, n, i, errors;
    reg [64*8-1:0] a_rd;
    reg [64*4-1:0] w_rd;
    reg [31:0] exp_rd;

    initial begin
        errors = 0;
        fd = $fopen("vectors/dot64.txt", "r");
        if (fd == 0) begin
            $display("ERROR: cannot open vectors/dot64.txt");
            $finish;
        end
        if ($fscanf(fd, "%d\n", n) != 1) begin
            $display("ERROR: cannot read count");
            $finish;
        end
        $display("running %0d vectors", n);

        @(posedge clk);
        @(posedge clk);
        rst_n = 1'b1;
        @(posedge clk);

        for (i = 0; i < n; i = i + 1) begin
            if ($fscanf(fd, "%h %h %h\n", a_rd, w_rd, exp_rd) != 3) begin
                $display("ERROR: fscanf failed at %0d", i);
                $finish;
            end
            @(negedge clk);
            act_flat = a_rd;
            wgt_flat = w_rd;
            valid_in = 1'b1;
            @(negedge clk);
            valid_in = 1'b0;
            if (!valid_out) begin
                $display("ERROR: valid_out low at %0d", i);
                errors = errors + 1;
            end else if (acc_out !== $signed(exp_rd)) begin
                $display("MISMATCH[%0d]: got %0d expected %0d", i, acc_out, $signed(exp_rd));
                errors = errors + 1;
            end
        end

        $fclose(fd);
        if (errors == 0)
            $display("PASS: %0d/%0d vectors", n, n);
        else
            $display("FAIL: %0d errors out of %0d", errors, n);
        $finish;
    end

endmodule
